public func polynomialUranusBitPattern(at index: Int) -> UInt64? {
    guard index >= 0 && index < 89505 else { return nil }
    switch index / 16384 {
    case 0: return polynomialUranusBits0[index - 0]
    case 1: return polynomialUranusBits1[index - 16384]
    case 2: return polynomialUranusBits2[index - 32768]
    case 3: return polynomialUranusBits3[index - 49152]
    case 4: return polynomialUranusBits4[index - 65536]
    case 5: return polynomialUranusBits5[index - 81920]
    default: return nil
    }
}

internal func decodeModelBits(_ payload: StaticString, count: Int) -> [UInt64] {
    payload.withUTF8Buffer { bytes in
        precondition(bytes.count == (count * 64 + 6) / 7)
        return Array(unsafeUninitializedCapacity: count) { storage, initializedCount in
            var cursor = 0
            var pending: UInt64 = 0
            var available = 0
            for index in 0..<count {
                var value: UInt64 = 0
                var offset = 0
                while offset < 64 {
                    if available == 0 {
                        pending = UInt64(bytes[cursor])
                        precondition(pending < 128)
                        cursor += 1
                        available = 7
                    }
                    let take = min(64 - offset, available)
                    value |= (pending & ((UInt64(1) << take) - 1)) << offset
                    pending >>= take
                    available -= take
                    offset += take
                }
                storage.initializeElement(at: index, to: value)
            }
            initializedCount = count
        }
    }
}
